import assert from 'node:assert/strict';
import {readFileSync,writeFileSync,mkdtempSync,rmSync} from 'node:fs';
import {join,resolve} from 'node:path';import {tmpdir} from 'node:os';import {pathToFileURL} from 'node:url';import {createHash} from 'node:crypto';
const root=resolve(process.env.HE_SOURCE_ROOT);assert.equal(process.version,'v24.22.1');
const sha=p=>createHash('sha256').update(readFileSync(join(root,p))).digest('hex');assert.equal(sha('src/memes.ts'),'cf477ac3f57827e77cc13b33aa9a177d5afa450abce3e84ba4c99fae25bf0756');
const {Store}=await import(pathToFileURL(join(root,'src/store.ts'))),{MemeService}=await import(pathToFileURL(join(root,'src/memes.ts')));
const A='a'.repeat(64),B='b'.repeat(64),C='c'.repeat(64);const tags=()=>({appearance:[],style:[],subject:[],emotion:[],intent:[],tone:[],intensity:[],memeMeaning:[],ocr:''});
const source=(sceneId='s',messageId='m',senderId='p')=>({sceneId,messageId,senderId});const ctx=(sceneId='s',simulation=false)=>({sceneId,simulation,sourceEvidence:[{...source(sceneId),available:true,isBot:false}]});
const asset=(id=A,patch={})=>({id,contentHash:id,knownOnly:false,format:'png',bytes:123,width:3,height:2,frames:1,sources:[source()],tags:tags(),analyzed:true,available:true,shared:false,privacyReviewed:false,favorite:false,disabled:false,preference:0,usageCount:0,createdAt:'2026-11-08T00:00:00.000Z',...patch});
const cases=[];
async function run(name,initial,actions){const store=new Store(':memory:'),dir=mkdtempSync(join(tmpdir(),'meme-live-oracle-'));let service;try{for(const id of ['s','other','off'])store.saveScene({id,kind:'group',adapterId:'synthetic',accountId:'account',platformSceneId:id,name:'Synthetic',participationEnabled:true,learningEnabled:id!=='off',proactiveEnabled:false});service=new MemeService(store,dir);for(const row of initial)service.write(row);const steps=[];for(const action of actions){let result=null,error;try{switch(action.method){case'update':result=service.update(action.id,action.patch);break;case'include':result=service.adminSetIncluded(action.id,action.included);break;case'promote':result=service.promoteKnown(action.ctx,action.id);break;case'feedback':service.recordFeedback(action.ctx,action.id,action.feedback);break;case'recall':result=service.recall(action.scene,action.message);break;case'usage':service.recordUsage(action.ctx,action.id);break;case'search':result=service.search(action.ctx,action.query,action.tags??[]);break;case'page':result=service.adminPage(action.input);break;case'restart':service=new MemeService(store,dir);break;case'get':result=service.adminGet(action.id)??null;break;default:throw Error('unknown_action')}}catch(e){error=e.message};const snapshot=service.adminList();const clean=v=>JSON.parse(JSON.stringify(v,(k,x)=>k==='lastUsedAt'?'TIMESTAMP':x));steps.push({action,result:clean(result),...(error?{error}:{}),snapshot:clean(snapshot)})}cases.push({name,initial,steps})}finally{await service?.dispose();store.close();rmSync(dir,{recursive:true,force:true})}}
await run('manual-state-known-review',[asset(A,{knownOnly:true,available:false})],[{method:'update',id:A,patch:{available:true}},{method:'include',id:A,included:true},{method:'update',id:A,patch:{shared:true}},{method:'update',id:A,patch:{shared:true,privacyReviewed:true}},{method:'include',id:A,included:false},{method:'promote',ctx:ctx(),id:A},{method:'update',id:A,patch:{disabled:true}},{method:'include',id:A,included:true}]);
await run('tag-revision-feedback-recall',[asset(A)],[{method:'update',id:A,patch:{tags:{...tags(),intent:['happy','happy'],ocr:'庆祝'}}},{method:'feedback',ctx:ctx(),id:A,feedback:{source:source(),positive:true}},{method:'feedback',ctx:ctx(),id:A,feedback:{source:source(),positive:false}},{method:'usage',ctx:ctx(),id:A},{method:'recall',scene:'s',message:'m'},{method:'usage',ctx:ctx(),id:A}]);
await run('recognition-and-pagination',[asset(A,{tags:{...tags(),intent:['unhappy']}}),asset(B,{shared:true,privacyReviewed:true,tags:{...tags(),intent:['happy']}}),asset(C,{knownOnly:true,available:false,tags:{...tags(),ocr:'100% private'}})],[{method:'search',ctx:ctx('other'),query:'happy'},{method:'search',ctx:ctx(),query:'开心'},{method:'search',ctx:ctx(),query:'unhappy'},{method:'page',input:{query:'happy',page:50,pageSize:1}},{method:'page',input:{query:'100%',state:'known'}},{method:'page',input:{scope:'scene:s',page:2,pageSize:2}},{method:'page',input:{state:'available',scope:'shared'}}]);
await run('restart-state-and-setting-errors',[asset(A,{analysisState:'retrying',analysisNextRetryAt:'2026-11-08T00:00:01.000Z'})],[{method:'restart'},{method:'get',id:A},{method:'update',id:A,patch:{favorite:'yes'}},{method:'update',id:A,patch:{tags:{...tags(),intent:42}}},{method:'update',id:B,patch:{favorite:true}}]);
const keys=new Set();function collect(v){if(Array.isArray(v)){v.forEach(collect);return}if(v&&typeof v==='object'){for(const [k,x]of Object.entries(v)){keys.add(k);if(k==='sources')for(const source of x)keys.add(JSON.stringify(source));collect(x)}}}cases.forEach(collect);const comparisons=[...keys].flatMap(a=>[...keys].map(b=>[a,b,a.localeCompare(b)]));
const output=JSON.stringify({comparisons,node:process.version,hashes:Object.fromEntries(['src/memes.ts','src/store.ts','src/memory/recovery/ledger.ts'].map(p=>[p,sha(p)])),cases},null,2)+'\n';writeFileSync(new URL('live-oracle.json',import.meta.url),output);console.log(`${cases.length} actual live MemeService source traces`);
